import { ethers } from 'ethers';

// ═══════════════════════════════════════════════════════════════
//  Base Mainnet Addresses
// ═══════════════════════════════════════════════════════════════

const USDC  = '0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913';
const WETH  = '0x4200000000000000000000000000000000000006';

// Aerodrome CL
const POSITION_MANAGER = '0x827922686190790b37229fd06084350E74485b72';
const SWAP_ROUTER      = '0xBE6D8f0d05cC4be24d5167a3eF062215bE6D18a5';
const AERO_POOL        = '0xb2cc224c1c9feE385f8ad6a55b4d94E92359DC59';

// Aave V3 on Base
const AAVE_POOL    = '0xA238Dd80C259a72e81d7e4664a9801593F98d1c5';
const A_WETH       = '0xD4a0e0b9149BCee3C920d2E00b5dE09138fd8bb7';
const A_USDC       = '0x4e65fE4DbA92790696d040ac24Aa414708F5c0AB';
const V_DEBT_USDC  = '0x59dca05b6c26dbd64b5381374aAaC5CD05644C28';
const V_DEBT_WETH  = '0x24e6e0795b3c7c71D965fCc4f371803d1c1DcA1E';

const DEPOSIT_CAP = BigInt('50000000000'); // 50,000 USDC (6 decimals)

// ═══════════════════════════════════════════════════════════════
//  Compiled Bytecodes
// ═══════════════════════════════════════════════════════════════

const IMPL_BYTECODE = '';

const PROXY_BYTECODE = '';

// ═══════════════════════════════════════════════════════════════
//  Initialize ABI (for encoding calldata)
// ═══════════════════════════════════════════════════════════════

const INIT_ABI = [{
  name: 'initialize',
  type: 'function',
  inputs: [{
    name: 'p',
    type: 'tuple',
    components: [
      { name: 'usdc', type: 'address' },
      { name: 'weth_', type: 'address' },
      { name: 'positionManager_', type: 'address' },
      { name: 'swapRouter_', type: 'address' },
      { name: 'aeroPool_', type: 'address' },
      { name: 'aavePool_', type: 'address' },
      { name: 'aWeth_', type: 'address' },
      { name: 'aUsdc_', type: 'address' },
      { name: 'vDebtUsdc_', type: 'address' },
      { name: 'vDebtWeth_', type: 'address' },
      { name: 'admin_', type: 'address' },
      { name: 'depositCap_', type: 'uint256' }
    ]
  }]
}];

export const config = { maxDuration: 120 };

export default async function handler(req, res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
  if (req.method === 'OPTIONS') return res.status(200).end();
  if (req.method !== 'POST') return res.status(405).json({ error: 'POST only' });

  const deployerKey = process.env.UNSTAKE_WALLET_PRIVATE_KEY;
  if (!deployerKey) {
    return res.status(500).json({ error: 'UNSTAKE_WALLET_PRIVATE_KEY not configured' });
  }

  try {
    const provider = new ethers.JsonRpcProvider('https://mainnet.base.org');
    const wallet = new ethers.Wallet(deployerKey, provider);

    console.log('[deploy-auto-vault] Deploying from:', wallet.address);

    // Check ETH balance for gas
    const ethBalance = await provider.getBalance(wallet.address);
    const ethBal = Number(ethBalance) / 1e18;
    if (ethBal < 0.002) {
      return res.status(400).json({ error: 'Not enough ETH for gas. Balance: ' + ethBal.toFixed(6) + ' ETH (need ~0.002)' });
    }

    // Implementation already deployed on Base mainnet
    const implAddress = '0x989B4A7b21d6c9Ad4447F3eF471135B3117de306';
    console.log('[deploy-auto-vault] Using implementation:', implAddress);

    // ─── Encode initialize() calldata ───
    console.log('[deploy-auto-vault] Encoding initialize calldata...');
    const iface = new ethers.Interface(INIT_ABI);
    const initData = iface.encodeFunctionData('initialize', [{
      usdc: USDC,
      weth_: WETH,
      positionManager_: POSITION_MANAGER,
      swapRouter_: SWAP_ROUTER,
      aeroPool_: AERO_POOL,
      aavePool_: AAVE_POOL,
      aWeth_: A_WETH,
      aUsdc_: A_USDC,
      vDebtUsdc_: V_DEBT_USDC,
      vDebtWeth_: V_DEBT_WETH,
      admin_: wallet.address,
      depositCap_: DEPOSIT_CAP
    }]);

    // ─── Deploy ERC1967Proxy (with explicit nonce to avoid caching) ───
    console.log('[deploy-auto-vault] Deploying ERC1967Proxy...');
    const nonce = await provider.getTransactionCount(wallet.address, 'latest');
    console.log('[deploy-auto-vault] Using nonce:', nonce);
    const proxyFactory = new ethers.ContractFactory(
      ['constructor(address implementation, bytes data)'],
      PROXY_BYTECODE,
      wallet
    );
    const proxyContract = await proxyFactory.deploy(implAddress, initData, { nonce });
    await proxyContract.waitForDeployment();
    const proxyAddress = await proxyContract.getAddress();
    console.log('[deploy-auto-vault] Proxy (vault):', proxyAddress);

    return res.status(200).json({
      success: true,
      proxyAddress,
      implementationAddress: implAddress,
      admin: wallet.address,
      network: 'base',
      depositCap: '50000 USDC',
      nextSteps: [
        'Set AUTO_VAULT_ADDRESS=' + proxyAddress + ' in basisubi/index.html',
        'Deploy keeper to Railway with AUTO_VAULT_ADDRESS=' + proxyAddress,
        'Set KEEPER_PRIVATE_KEY on Railway',
        'Verify implementation: npx hardhat verify --network base ' + implAddress,
        'Test: deposit small amount (10 USDC), then trigger rebalance'
      ]
    });
  } catch (e) {
    console.error('[deploy-auto-vault] Error:', e);
    return res.status(500).json({ error: e.reason || e.message });
  }
}
